var SPS={"Accursed":{"":[[1,"Spare the Dying"],[3,"False Life"],[5,"Mirror Image"]]},"Cursed-Blood":{"Spirit Twin":[[1,"Mage Hand"]],"Watchful Twin":[[1,"Cosmic Eye"],[3,"Detect Magic"],[5,"See Invisibility"]]},"Demidritch":{"":[[1,"Cosmic Eye"]]},"Deep One Dwarf":{"":[[1,"Dancing Lights"]]}};
var SPC={"Manikin":{"size":"Small or Medium","speed":30,"dark":0,"type":"Construct","lin":{"label":"Integrated Gold Plating","opts":["Infiltrator","Sentinel","Tormentor"]},"linText":{"Infiltrator":"Your base AC is 11 + Dexterity modifier. You count as unarmored for features that need no armor. You have Advantage on Dexterity (Stealth) checks.","Sentinel":"Your base AC is 13 + Dexterity modifier (maximum +2) or Strength modifier (maximum +3). You count as wearing Medium armor, so you suffer the drawbacks of it if you lack Medium armor training.","Tormentor":"Your base AC is 16 + Strength modifier (maximum +2). You count as wearing Heavy armor, so you suffer the drawbacks of it if you lack Heavy armor training. You have Disadvantage on Dexterity (Stealth) checks."},"opts":{"label":"Service Model","n":1,"list":[["Custodian","Advantage on ability checks to end the Grappled condition. You count as one size larger for carrying capacity. Reaction, when a creature within 5 feet is targeted by an attack: if the creature is willing, swap places with it and become the target. Uses equal your Proficiency Bonus per Long Rest.",{}],["Handler","Proficiency in Stealth and with the Disguise Kit. You can embed up to two Melee weapons in your body, each with the Finesse or Light property. Swapping one or both for weapons you hold takes 1 hour, which can be a Short Rest. You draw and stow them as normal and cannot be disarmed of them unless your arms are cut off.",{"skills":["Stealth"]}],["Thespian","Proficiency in Performance. Bonus Action: link yourself to a willing creature you can see within 30 feet by immaterial strings for 1 hour. If that creature leaves some of its movement unused on its turn (use its highest Speed), you can use your Reaction at the end of its turn to move up to the unused amount. After you link, finish a Short or Long Rest to do so again.",{"skills":["Performance"]}]]},"traits":[["Born to Serve","You cannot hate or resent your creators. You have Disadvantage on Wisdom (Insight) checks."],["Electric Heart","Resistance to Lightning damage."],["Integrated Gold Plating","Your body is its own armor. Armor gives you no AC, but a Shield works as normal. Pick Infiltrator, Sentinel or Tormentor when you pick the species. It sets your base AC and may give a Stealth effect."],["Living Material","You need no food, drink or air. Immunity to the Poisoned condition."],["Service Model","Pick Custodian, Handler or Thespian when you pick the species. Each gives a different support benefit."],["Age","You do not age. Over time your materials lose their magic and you eventually turn back into inanimate objects."]],"hb":"SGEH24"},"Accursed (Steinhardt)":{"size":"Medium","speed":30,"dark":60,"type":"Aberration","fx":{"moves":{"climb":"walk"}},"spAb":"choose","spAbTrait":"Legacy of a Thousand Young","traits":[["Darkvision","Darkvision 60 ft."],["Climb Speed","You have a Climb Speed equal to your Speed."],["Blood Moon's Call","If you sleep under a Blood Moon, the Black Goat sends a dream that places a compulsion in your mind. When you wake, you are under the Suggestion spell (save DC 16) and must follow the order. A successful save resists it."],["Eldritch Endurance","Resistance to Necrotic damage."],["Legacy of a Thousand Young","You know Spare the Dying. At level 3 you always have False Life prepared and at level 5 Mirror Image. You can cast each once without a slot and regain that use on a Long Rest. You can also cast them with spell slots. Intelligence, Wisdom or Charisma is the spell ability, chosen with the species."]],"hb":"SGEH24"},"Cursed-Blood":{"size":"Small","speed":25,"dark":0,"type":"Humanoid","fx":{"moves":{"climb":"walk"}},"spAb":"choose","spAbTrait":"Together Forever","lin":{"label":"Together Forever","opts":["Hungering Twin","Spirit Twin","Watchful Twin"]},"linFx":{"Watchful Twin":{"dark":120}},"linText":{"Hungering Twin":"Level 1: your stomach is bigger inside. It holds up to 250 pounds and 32 cubic feet, and a creature inside can breathe for 1 minute. Nonmagical items inside are destroyed by psychic energy after 24 hours. If you die, you harmlessly regurgitate everything. Level 3: pick Acid, Cold, Fire or Poison. When you take damage of that type, reduce it by your Proficiency Bonus. Level 5: nonmagical items are no longer destroyed, and the stomach holds 500 pounds and 64 cubic feet.","Spirit Twin":"Level 1: you have telepathy out to 5 feet times your character level. A creature without telepathy that gets your messages cannot answer you mentally. You also know Mage Hand. Level 3: you can turn a Critical Hit against you into a normal hit. After you do, finish a Short or Long Rest to do so again. Level 5: a creature without telepathy that gets your messages can reply to you in a language it knows.","Watchful Twin":"Level 1: Darkvision 120 ft. You also know Cosmic Eye. Level 3: you learn Detect Magic. Level 5: you learn See Invisibility."},"traits":[["Climb Speed","You have a Climb Speed equal to your Speed. You cannot use it while wearing Medium or Heavy armor."],["Together Forever","Your dead twin lives on in your stomach. Pick Hungering Twin, Spirit Twin or Watchful Twin. You get the level 1 benefit now and more at levels 3 and 5. A spell you learn here is always prepared, castable once without a slot per Long Rest, or with spell slots. Intelligence, Wisdom or Charisma is the spell ability, chosen with the species."],["Vigilant","You cannot be surprised. When you roll Initiative, add your Proficiency Bonus to the roll."],["Age","You mature at 5 years and usually live about 60 years, rarely up to 100."]],"hb":"SGEH24"},"Demidritch":{"size":"Medium","speed":30,"dark":120,"type":"Humanoid","spAb":"CHA","lin":{"label":"Unleash Infinity","opts":["Nebulare","Oculare"]},"linText":{"Nebulare":"Creatures other than your allies within 10 feet make a Dexterity save (DC 8 + Charisma modifier + Proficiency Bonus) or take Radiant damage of a number of d6s equal to your Proficiency Bonus. You shed Bright Light in 10 feet and Dim Light 10 feet beyond. A 20-foot Emanation from you is Difficult Terrain for enemies you can see. At level 12 the Emanation grows to 60 feet, and you gain a Fly Speed of 30 feet and can hover.","Oculare":"No creature within 60 feet gets Advantage on attack rolls against you because it has the Invisible condition. At level 12 you also grow eye-covered wings that give you a Fly Speed of 30 feet, and you have Truesight out to 60 feet."},"traits":[["Darkvision","Darkvision 120 ft."],["Astral Sight","Advantage on saving throws against the Blinded condition. You know Cosmic Eye, with Charisma as the spell ability."],["Shard of Infinity","Resistance to Cold damage."],["Unleash Infinity","From level 3, as a Bonus Action, transform for 1 minute or until you end it (no action). Pick Nebulare or Oculare when you pick the species. After you transform, finish a Long Rest to do so again."],["Age","You mature at 10 years. Your body decays quickly and you live up to 60 years."]],"hb":"SGEH24"},"Scourgeborne":{"size":"Medium","speed":30,"dark":0,"type":"Monstrosity","attacks":[{"n":"Feral Limbs","die":"1d6","type":"Piercing","range":"5 ft","ab":"STR","note":"Horns, claws or fangs from your mutation. Piercing damage replaces the normal damage of an Unarmed Strike. The die is 1d8 if your alignment is Evil."}],"lin":{"label":"Monstrous Lineage","opts":["Aranea","Belua","Cervus","Vespertilio"]},"linFx":{"Aranea":{"moves":{"climb":30}},"Cervus":{"speedSet":40},"Vespertilio":{"senses":[["Blindsight",30,"Monstrous Lineage","Disadvantage on ability checks and attack rolls that need sight beyond this range"]]}},"linText":{"Aranea":"Level 1: Climb Speed 30 feet. In water you have Disadvantage on all ability checks and attack rolls. Level 3: you climb difficult surfaces, ceilings included, with no check. After using this for 1 minute, finish a Long Rest to do so again. Level 5: you can use the level 3 trait for a number of minutes equal to your Proficiency Bonus, regained on a Long Rest.","Belua":"Level 1: Advantage on Wisdom (Perception) checks that use hearing or smell. When you cause a creature to become Bloodied, you take 1d4 Psychic damage. Level 3: Bonus Action, make an Unarmed Strike against a creature in reach to feed. On a hit you regain Hit Points equal to the damage dealt. After you use this, finish a Long Rest to do so again. Level 5: you can use the level 3 trait a number of times equal to your Proficiency Bonus, regained on a Long Rest.","Cervus":"Level 1: Speed 40 feet. Standing up from Prone costs 5 extra feet. Level 3: if you move at least 20 feet straight at a creature and hit it with a melee attack in the same turn, it makes a Strength save (DC 8 + Strength modifier + Proficiency Bonus) or falls Prone. You can then use a Bonus Action to make one melee attack against it. After you force this save, finish a Long Rest to do so again. Level 5: you can use the level 3 trait a number of times equal to your Proficiency Bonus, regained on a Long Rest.","Vespertilio":"Level 1: Blindsight 30 feet. You have Disadvantage on ability checks and attack rolls that need sight beyond that range. Level 3: Bonus Action, gain a Fly Speed of 30 feet until the end of your turn. You fall if nothing holds you up when the turn ends. After you use this, finish a Short or Long Rest to do so again. Level 5: you can use the level 3 trait a number of times equal to your Proficiency Bonus, regained on a Short or Long Rest."},"opts":{"label":"Born of Madness","n":1,"list":[["Good Alignment","Advantage on saving throws to avoid or end Madness. Disadvantage on Charisma (Intimidation) checks.",{}],["Neutral Alignment","Your alignment gives you no benefit and no penalty.",{}],["Evil Alignment","Add your Proficiency Bonus to your Dexterity saving throws. Disadvantage on saving throws to avoid or end Madness. Your Feral Limbs die is 1d8.",{}]]},"traits":[["Born of Madness","Your body is a result of exposure to eldritch madness. Pick the option that matches your alignment."],["Eldritch Curse","You are immune to spells that change your form, such as Alter Self and Polymorph."],["Feral Limbs","Your horns, claws or fangs make Unarmed Strikes that deal 1d6 + Strength modifier Piercing damage instead of the normal damage. The die is 1d8 if your alignment is Evil."],["Monstrous Lineage","Pick Aranea, Belua, Cervus or Vespertilio. You get the level 1 benefit now and more at levels 3 and 5."],["Age","You age at the rate of the race you were before the change."]],"hb":"SGEH24"},"Deep One Dwarf":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","fx":{"moves":{"swim":25}},"spAb":"CHA","opts":{"label":"Slumbering Legacy","n":1,"list":[["Coiling Arm","Your arm is a writhing mass of tentacles. On your turn, right after you hit an enemy with a melee attack, you can use a Bonus Action to make an Unarmed Strike with the Grapple option against it. Normal grappling limits apply.",{}],["Brutal Pincers","Your forearm is a pincer you can use for Unarmed Strikes. A hit deals 1d6 + Strength modifier Piercing damage instead of Bludgeoning. Against a creature you are grappling the die is 1d10. You cannot do precise work with this arm.",{}],["Mucoid Extremities","Cupped, palmed hands and feet raise your Swim Speed to 35 feet and give you a Climb Speed of 20 feet.",{"moves":{"swim":35,"climb":20}}]]},"traits":[["Amphibious","You breathe air and water."],["Cosmic Knowledge","On Intelligence (History) checks about the origin of an eldritch item or construction, you count as having proficiency and Expertise in History."],["Dreamer's Curse","Dreams of the Slumbering One cloud your mind. You have Disadvantage on ability checks and saving throws to discern illusions."],["Guiding Light","You know Dancing Lights, with Charisma as the spell ability."],["Illusory Body","An illusion makes you look like a typical hill dwarf. Other Deep Ones see through it. You have Advantage on Charisma (Deception) checks against creatures that cannot see through it."],["Otherworldly Resistance","Resistance to Cold damage. Advantage on saving throws to avoid or end the Poisoned condition."],["Slumbering Legacy","Pick Coiling Arm, Brutal Pincers or Mucoid Extremities when you pick the species."],["Dreamer's Gift (optional)","From level 5, when you fail an ability check or saving throw, you can succeed instead. After you use this, you cannot do so again until the Dreamer replaces one of your D20 Test results with a 1, at the GM's choice of moment. You are also immune to the Curse of the Slumbering Moon."],["Age","You mature at 10 years and cannot die of old age. At 50 your mind fails and you become a brainless servant of He Who Lies Dreaming."]],"hb":"SGEH24"}};
var DFS={};
var SPR=[["Amputate",7,"Evocation",["Druid","Warlock","Wizard"],"Action","Touch","V, S","Instantaneous",0,0,"","Touch. Melee spell attack: 10d8 Slashing and a limb is torn off. Creatures with Slashing immunity, Legendary Actions or too big (GM call) take an extra 5d8 Slashing instead of losing a limb. +4d8 and +2d8 extra per slot level above 7.","SGEH24",["Druid","Warlock","Wizard"]],["Ancestral Bond",5,"Divination",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"Action","Touch","V, S, M","Instantaneous",0,1,"WIS","Touch a Humanoid corpse (may be consumed). Learn how many relatives and descendants it left alive. Destroy the corpse to target one descendant: Wisdom save or you learn its exact location.","SGEH24",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Arm Cannon",2,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","30 ft","V, S","1 round",0,0,"STR","Range 30 ft. Ranged spell attack, 4d8 Piercing, then Strength save or pushed 15 ft. Into an obstacle: Restrained until end of its next turn. Large or larger have Advantage on the save. +1d8 and +5 ft per slot level above 2.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Aspect of Death",9,"Conjuration",["Druid","Warlock"],"Action","Self","V, S, M","Up to 1 minute",1,0,"","Concentration, 1 minute. Material: a skull of a fallen hero set with jewels worth 4,000 GP+. A Huge bone avatar surrounds you and moves with you: Cover, Resistance to all damage, Grappled immunity, +1 to spell attacks and saves, and your Bludgeoning, Piercing and Slashing spells are cast 2 slot levels higher (max 9).","SGEH24",["Druid","Warlock"]],["Astral Barrage",3,"Conjuration",["Druid","Ranger","Sorcerer","Wizard"],"Action","60 ft","V, S","Up to 1 minute",1,0,"DEX","Range 60 ft, Concentration, 1 minute. Dexterity save or 7d6 Bludgeoning. Use a Magic action on later turns to hit again. Your Speed is halved. +2d6 per slot level above 3.","SGEH24",["Druid","Ranger","Sorcerer","Wizard"]],["Bestial Roar",0,"Transmutation",["Bard","Druid","Sorcerer","Warlock"],"Action","Self (10 ft emanation)","V","Instantaneous",0,0,"STR","10-ft Emanation. Strength save or pushed 10 ft away and Prone. Area grows to 15, 20 and 25 ft at levels 5, 11 and 17.","SGEH24",["Bard","Druid","Sorcerer","Warlock"]],["Blind Ambush",2,"Conjuration",["Bard","Druid","Ranger","Warlock"],"Action","60 ft","V, S, M","1 minute",0,0,"","Range 60 ft, 1 minute. A trap on the ground in a 10-ft square. First creature to move 5 ft or more in it triggers a maw for 2d10 Piercing to all in the square and one is knocked Prone. +1d10 per slot level above 2.","SGEH24",["Bard","Druid","Ranger","Warlock"]],["Bludgeoning Horror",2,"Conjuration",["Sorcerer","Warlock","Wizard"],"Action","15 ft","V, S, M","Instantaneous",0,0,"","Range 15 ft. Melee spell attack, 3d6 Bludgeoning. A Critical Hit also Stuns until the start of your next turn. +1d6 and +5 ft range per slot level above 2.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Bone Claws",1,"Transmutation",["Sorcerer","Warlock","Wizard"],"Bonus Action","30 ft","V, S, M","Up to 1 minute",1,0,"","Range 30 ft. Target's Unarmed Strikes deal an extra 1d4 Slashing. Concentration, 1 minute. Extra damage grows with slot level.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Bone Cocoon",2,"Abjuration",["Cleric","Druid","Paladin","Sorcerer","Warlock","Wizard"],"Reaction","30 ft","V, M","Up to 1 minute",1,0,"","Reaction when a creature within 30 ft drops to 0 HP. A bone cocoon (25 HP, AC 11 + your modifier) shields it, grants Cover, Restrained, and Advantage on Death Saves. Concentration, 1 minute. +25 HP per slot level above 2.","SGEH24",["Cleric","Druid","Paladin","Sorcerer","Warlock","Wizard"]],["Bone Shield",1,"Abjuration",["Druid","Ranger","Warlock"],"Reaction","Self","V, S","Instantaneous",0,0,"","Reaction. Reduce incoming damage by 1d12. If the attacker is within 10 ft, it takes Slashing damage equal to the amount reduced. +1d12 per slot level above 1.","SGEH24",["Druid","Ranger","Warlock"]],["Boneyard",7,"Necromancy",["Cleric","Sorcerer","Warlock","Wizard"],"24 hours","Touch","V, S, M","Until dispelled",0,0,"","Touch, 24 hours casting, until dispelled. Material: bones, incense and herbs worth 1,000 GP+ (consumed). A Sphere up to 120 ft radius: you sense Undead, creatures lose Necrotic and Piercing Resistance and Immunity, and you can raise dead non-Undead as controlled Undead for one turn. Fails over an existing Boneyard or Hallow.","SGEH24",["Cleric","Sorcerer","Warlock","Wizard"]],["Brittle Bone Throw",0,"Conjuration",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Instantaneous",0,0,"","Range 60 ft. Ranged spell attack, 1d8 Piercing. On a miss, redirect it at a creature within 30 ft of the target for 1d4 Piercing on a hit. Scales at 5, 11, 17.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Bury",8,"Transmutation",["Bard","Sorcerer","Wizard"],"Action","120 ft","V, S","Up to 10 minutes",1,0,"STR","Range 120 ft, Concentration, 10 minutes. 30-ft radius, 300-ft high Cylinder of crushing gravity. Creatures are Prone and take 4d6 Bludgeoning on entry or at turn start, need a Strength save to move or act, and can be pressed into the ground.","SGEH24",["Bard","Sorcerer","Wizard"]],["Calcified Memories",2,"Divination",["Warlock","Wizard"],"Action","Touch","V, S","Instantaneous",0,1,"","Touch the bones of a dead creature to see a ghostly replay of its last 6 seconds (its own actions only). No effect on Undead. Once per corpse per 24 hours.","SGEH24",["Warlock","Wizard"]],["Chisel Skull",5,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","S, M","Instantaneous",0,0,"CON","Range 60 ft. Constitution save: 8d10 Piercing and Paralyzed until the end of its next turn (half damage only on success). Creatures without a skull are immune.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Cosmic Eye",0,"Transmutation",["Sorcerer"],"Action","150 ft","M","Instantaneous",0,0,"","Range 150 ft. Ranged spell attack, 1d8 Necrotic. On a Critical Hit, any damage die of 4 or lower counts as a 5. Scales at 5, 11, 17.","SGEH24",["Sorcerer"]],["Crush",7,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Instantaneous",0,0,"STR","Range 60 ft. Material: bone powder. Strength save or 12d10 Bludgeoning and Stunned until the start of your next turn. +1 target per slot level above 7.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Dampen Gravity",3,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","Self (60 ft emanation)","V, S, M","1 hour",0,0,"","60-ft Emanation, 1 hour. Chosen creatures double their jump distance, gain +10 ft Speed, Advantage on Dexterity (Acrobatics) and ignore fall damage while in the area.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Displacing Maw",3,"Conjuration",["Warlock","Wizard"],"Action","10 ft","V, S","Instantaneous",0,0,"STR","Range 10 ft. Your ribs open into a maw. Strength save: 4d8 Piercing and the target is moved to a ground point you choose within 60 ft (half damage only on success). +1d8 and +10 ft teleport range per slot level above 3.","SGEH24",["Warlock","Wizard"]],["Divine Order: Reveal",5,"Divination",["Bard","Cleric","Warlock"],"Bonus Action","30 ft","V, S","Instantaneous",0,0,"CHA","Range 30 ft, Bonus Action. Charisma save: on a fail you learn the target's alignment, type, ability scores, proficiencies, senses, languages, Vulnerabilities, Resistances, Immunities, CR and traits. On a success it is immune to this spell for 24 hours.","SGEH24",["Bard","Cleric","Warlock"]],["Divine Order: Sacrifice",9,"Conjuration",["Bard","Cleric","Warlock"],"Action","120 ft","V, S","Up to 1 minute",1,0,"CHA","Range 120 ft, Concentration, 1 minute. 8d6 Psychic and a Charisma save. Fail: pulled into the cosmos (Incapacitated, 3d6 Cold + 3d6 Psychic each turn, DC 20 Intelligence save or Short-Term Madness). Success: Long-Term Madness and the spell ends. Losing Concentration risks Long-Term Madness for you, and a d100 roll of 1 at the end opens a rift.","SGEH24",["Bard","Cleric","Warlock"]],["Divine Order: Transcend",7,"Divination",["Bard","Cleric","Warlock"],"Action","Self","V, S","Up to 1 minute",1,0,"INT","Concentration, 1 minute. Cast Warlock spells of level 5 or lower without slots or preparation. At the end of each of your turns, DC 18 Intelligence save or 2d10 Psychic. Two failures end the spell and give Short-Term Madness. A level 9 slot removes Concentration.","SGEH24",["Bard","Cleric","Warlock"]],["Dread Scarecrow",4,"Illusion",["Bard","Warlock","Wizard"],"Action","Self (30 ft emanation)","V, S, M","Up to 1 minute",1,0,"WIS","30-ft Emanation, Concentration, 1 minute. Wisdom save or Frightened. While so Frightened: Speed 0 and Prone. If it takes damage, it repeats the save at the end of its next turn. Needs a femur flute worth 50 GP+.","SGEH24",["Bard","Warlock","Wizard"]],["Electrify",1,"Evocation",["Ranger","Sorcerer","Wizard"],"Bonus Action","Self","V, S","1 round",0,0,"CON","Bonus Action, 1 round. Your next melee hit (weapon or spell) before your next turn deals 1d12 Lightning, and the target makes a Constitution save or is Stunned until its next turn starts. +1d12 per slot level above 1.","SGEH24",["Ranger","Sorcerer","Wizard"]],["Erupting Lightning",6,"Evocation",["Druid","Sorcerer","Wizard"],"Action","120 ft","V, S, M","Instantaneous",0,0,"DEX","Range 120 ft. Up to seven 5-ft Cubes of lightning, each touching another. Dexterity save: 7d10 Lightning and Prone (half damage on success). +2 Cubes per slot level above 6.","SGEH24",["Druid","Sorcerer","Wizard"]],["Fall",1,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","Self","V, M","Instantaneous",0,0,"","Material: an elastic band. Change which way gravity pulls you and fall 200 ft that way at once. Hitting a surface deals fall damage. +50 ft per slot level above 1.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Fling",4,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","Touch","V, S","Instantaneous",0,0,"DEX","Touch. Strength save: 6d10 Bludgeoning and pushed 120 ft (half damage and no push on success). Creatures in its path take 1d10 plus 1d10 per size smaller. +1d10 and +30 ft per slot level above 4.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Forest of Dread",5,"Conjuration",["Sorcerer","Warlock","Wizard"],"Action","Self","V, S","Up to 10 minutes",1,0,"DEX","Concentration, 10 minutes. Bone trees fill a 30-ft radius, 20-ft high Cylinder around you. Chosen creatures make a Dexterity save: 4d8 Piercing (half on success). Area is Difficult Terrain that deals 2d8 Piercing per 5 ft moved, and gives Cover. You are immune.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Fractured Shell",1,"Transmutation",["Warlock","Wizard"],"Action","Touch","V, S, M","Up to 10 minutes",1,0,"","Touch, willing creature takes 1 Piercing. Once per turn, a melee attacker that hits the target takes 2d4 Piercing. Concentration, 10 minutes. +2d4 per slot level above 1.","SGEH24",["Warlock","Wizard"]],["Gravitational Distortion",4,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S","Instantaneous",0,0,"STR","Range 60 ft. 30-ft radius Sphere. Strength save: 6d6 Bludgeoning and pushed 30 ft (half damage and no push on success). +1d6 per slot level above 4.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Graviturgic Smite",2,"Evocation",["Paladin"],"Bonus Action","Self","V","Up to 1 minute",1,0,"STR","Bonus Action, Concentration, 1 minute. Next weapon hit deals extra 3d4 Bludgeoning and the target makes a Strength save or its Speed drops to 10 ft. On a success its Speed drops by 10 ft. +2d4 per slot level above 2.","SGEH24",["Paladin"]],["Gravity Barrier",4,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S","Up to 10 minutes",1,0,"STR","Range 60 ft, Concentration, 10 minutes. Wall of gravity (30 ft long, 10 ft high, 1 ft thick, or a ring 20 ft across and 20 ft high). Difficult Terrain, blocks ranged weapons, crossing it risks 4d8 Bludgeoning, Prone and Speed 0. +1d8 per slot level above 4.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Gravity Leap",1,"Transmutation",["Druid","Ranger","Sorcerer"],"Action","Self","V, S","1 minute",0,0,"STR","1 minute. Jump distance tripled. Once per turn right after you jump, creatures within 5 ft of the space you left make a Strength save or fall Prone.","SGEH24",["Druid","Ranger","Sorcerer"]],["Gravity Spike",0,"Transmutation",["Druid","Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S","Instantaneous",0,0,"DEX","Range 60 ft. Dexterity save: 1d6 Piercing and Prone (half damage on success). Scales at 5, 11, 17.","SGEH24",["Druid","Sorcerer","Warlock","Wizard"]],["Gravity Storm",2,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","120 ft","V, S","2 rounds",0,0,"DEX","Range 120 ft, 2 rounds. 20-ft Sphere, Dexterity save at cast and at the start of each of your turns: 2d6 Bludgeoning and Prone (half damage on success). +2d6, +5 ft radius and +1 round per slot level above 2.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Gravity Well (Steinhardt)",1,"Evocation",["Cleric","Druid","Ranger","Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S","Instantaneous",0,0,"","Range 60 ft. Ranged spell attack, 2d8 Force and pulled 20 ft toward you in a straight line. +1d8 per slot level above 1.","SGEH24",["Cleric","Druid","Ranger","Sorcerer","Warlock","Wizard"]],["Gravity Whip",0,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","10 ft","V, S","Instantaneous",0,0,"","Range 10 ft. Melee spell attack, 1d4 Bludgeoning, push 5 ft and Speed -10 ft until your next turn. Scales at 5, 11, 17.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Jumping Jolt",4,"Evocation",["Sorcerer","Wizard"],"Action","60 ft","V, S","Instantaneous",0,0,"","Range 60 ft. Ranged spell attack, 4d12 Lightning (half on a miss). Then it can jump to another creature within 20 ft of the target, up to 4 times, never the same target twice. +1d12 and +1 jump per slot level above 4.","SGEH24",["Sorcerer","Wizard"]],["Lightning Charged",2,"Evocation",["Druid","Ranger","Sorcerer","Wizard"],"Action","Touch","V, S, M","10 minutes",0,0,"","Touch, 10 minutes. A creature becomes charged. Each time it casts a Touch spell on, hits with a melee attack roll, or ends its turn grappling or Grappled by another creature, that creature takes 1d6 Lightning. Ends after 6 discharges. +2 discharges per slot level above 2.","SGEH24",["Druid","Ranger","Sorcerer","Wizard"]],["Maiden of Bones",4,"Conjuration",["Warlock","Wizard"],"Action","60 ft","V, S, M","1 minute",0,0,"STR","Range 60 ft, 1 minute. Strength save or the target is sealed in a bone iron maiden: Incapacitated, Restrained, Cover, 3d6 Piercing at the start of each of its turns. It repeats the save at its turn end. Maiden: AC 10 + your modifier, 80 HP. +1d6 and +20 HP per slot level above 4.","SGEH24",["Warlock","Wizard"]],["Malicious Rancor",3,"Evocation",["Warlock"],"Action","60 ft","V, S, M","1 round",0,0,"WIS","Range 60 ft. Ranged spell attack, 1d10 Necrotic. Hit or miss, it explodes in a 10-ft Sphere: Wisdom save, 5d4 Psychic (half on success). Creatures entering or ending their turn there before your next turn repeat the save. +2d4 per slot level above 3.","SGEH24",["Warlock"]],["Marrow Transplant",4,"Necromancy",["Cleric","Druid"],"Action","30 ft","V, S, M","Instantaneous",0,0,"","Range 30 ft. Material: spinal bone and a 300 GP diamond (consumed). Ranged spell attack, 4d6 Necrotic. Another creature in range heals that much or, if dead under 1 minute, returns to life with that many HP. Targets need bones. +1d6 per slot level above 4.","SGEH24",["Cleric","Druid"]],["Osseous Cage",3,"Conjuration",["Druid","Warlock","Wizard"],"Action","Self","V, S","10 minutes",0,0,"","10-ft radius Sphere of bone around you, 10 minutes. Three-Quarters Cover. Only you can let creatures through (Reaction). Large or larger cannot enter. AC 12, 100 HP, vulnerable to Bludgeoning. +20 HP per slot level above 3.","SGEH24",["Druid","Warlock","Wizard"]],["Osseous Impalement",3,"Conjuration",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"DEX","Range 60 ft, Concentration, 1 minute. Up to 4 creatures on the ground. Dexterity save or 3d10 Piercing and impaled (held 5 ft up, Restrained, 1d10 Piercing at the start of each of its turns). Athletics check against your DC frees it. +1d10 per slot level above 3.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Osteophagia",9,"Conjuration",["Warlock","Wizard"],"Action","Touch","V, S","Instantaneous",0,0,"CON","Touch. Constitution save: on a fail the target dies, on a success it takes 10d6 Necrotic. Immune: no bones, or a CR or level equal to or higher than yours.","SGEH24",["Warlock","Wizard"]],["Otherworldly Gaze",2,"Divination",["Bard","Druid","Ranger"],"Action","Self","V, S","10 minutes",0,0,"","10 minutes. Advantage on Wisdom (Perception), sense eldritch creatures (Aberrations, Celestials, Fiends) within 120 ft, see true forms of shapechangers within 30 ft, ignore Blinded.","SGEH24",["Bard","Druid","Ranger"]],["Phalangeal Shot",1,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","Self","V, S","Instantaneous",0,0,"DEX","30-ft by 1-ft Line. Dexterity save or 2d8 Piercing. Your finger bones fire like bullets and regrow at once. +1d8 per slot level above 1.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Pressure Cage",2,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"STR","Range 60 ft, Concentration, 1 minute. 10-ft Sphere of Difficult Terrain. A creature entering or starting its turn there makes a Strength save or its Speed becomes 0 until its next turn. Move the sphere 20 ft as a Bonus Action. +5 ft radius per slot level above 2.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Radiant Bell",3,"Abjuration",["Bard","Cleric"],"Action","Self","V, S, M","Instantaneous",0,0,"","Material: silvered choir bell worth 5 GP+ (consumed). Choose creatures within 30 ft. For each, end one of Charmed, Frightened, Poisoned, Petrified or Stunned. Fails on a Deafened target.","SGEH24",["Bard","Cleric"]],["Radiant Slaughter",3,"Conjuration",["Cleric","Paladin","Warlock"],"Action","Self (30 ft emanation)","V, S, M","Instantaneous",0,0,"DEX","30-ft Emanation. Dexterity save: 2d6 Force + 3d6 Radiant and Prone (half damage on success). Creatures within 5 ft of you save with Disadvantage. +1d6 of each per slot level above 3.","SGEH24",["Cleric","Paladin","Warlock"]],["Rolling Bones",2,"Divination",["Cleric","Druid","Warlock","Wizard"],"1 minute","Self","V, S, M","Instantaneous",0,1,"","1 minute casting, bones worth 100 GP. Roll 1d6 for an omen about Hostile creatures in the next hour. 1 consumes the bones and deals 1 Psychic. Later castings risk false readings.","SGEH24",["Cleric","Druid","Warlock","Wizard"]],["Rubber Bones",3,"Transmutation",["Sorcerer","Warlock","Wizard"],"Action","Touch","V, S","Up to 10 minutes",1,0,"DEX","Touch, willing creature, Concentration, 10 minutes. End Grappled for 5 ft of movement, squeeze through a space two sizes smaller, Advantage on Dexterity saves, Resistance to Bludgeoning, +5 ft melee reach. +1 target per slot level above 3.","SGEH24",["Sorcerer","Warlock","Wizard"]],["Rupturing Curse",2,"Evocation",["Warlock","Wizard"],"Action","60 ft","V, S","Up to 1 minute",1,0,"CON","Range 60 ft, Concentration, 1 minute. Constitution save or 3d10 Piercing and Prone. If it then takes Bludgeoning damage of 5 times its Constitution modifier (min 5) in one turn, its skeleton shatters and its Speed is 0. +1d10 per slot level above 2.","SGEH24",["Warlock","Wizard"]],["Silvered Shell",1,"Transmutation",["Paladin","Ranger"],"Bonus Action","Self","V, S, M","1 minute",0,0,"","Bonus Action, touch a weapon. It becomes Moongilded and deals an extra 1d4 Force while you hold it. 1 minute, longer with higher slots.","SGEH24",["Paladin","Ranger"]],["Skeletal Tail",2,"Conjuration",["Druid","Ranger"],"Bonus Action","Self (15 ft emanation)","V, S, M","1 minute",0,0,"","Bonus Action, 1 minute. When a creature moves into or within a 15-ft Emanation around you, use a Reaction for a melee spell attack: 2d4 + your modifier Piercing and it is pulled to the nearest free space next to you. +2d4 per slot level above 2.","SGEH24",["Druid","Ranger"]],["Spectral Fury",3,"Conjuration",["Paladin","Ranger"],"Action","30 ft","V, S, M","Instantaneous",0,0,"","Range 30 ft. Three spectral doubles each make a melee spell attack for 4d8 of your weapon's damage type. Then a Bonus Action dashes you 30 ft in a line toward a target with no Opportunity Attacks and one melee attack. +2d8 per double per slot level above 3.","SGEH24",["Paladin","Ranger"]],["Spectral Slash",1,"Conjuration",["Paladin","Ranger"],"Bonus Action","20 ft","V, S, M","Instantaneous",0,0,"","Range 20 ft, Bonus Action. Melee spell attack, 1d8 of your weapon's damage type. Then a Magic action lets you dash 20 ft in a line toward the target and make the Attack action against it. +1d8 and +10 ft per slot level above 1.","SGEH24",["Paladin","Ranger"]],["Starfall",5,"Enchantment",["Druid","Sorcerer","Wizard"],"Bonus Action","Self (30 ft emanation)","V, S","Up to 1 minute",1,0,"","30-ft Emanation, Bonus Action, Concentration, 1 minute. On cast and each later turn as a Bonus Action, call stars on chosen creatures in the area for 3d4 Radiant each. +1d4 per slot level above 5.","SGEH24",["Druid","Sorcerer","Wizard"]],["Unbound Chamber",6,"Transmutation",["Druid","Sorcerer","Wizard"],"10 minutes","500 ft","V, S","8 hours",0,1,"","Range 500 ft, 1 minute casting, 8 hours. An enclosed space up to 200 ft in each dimension. Inside, creatures take no fall damage, triple their jump distance, have a Fly Speed equal to their Speed and can hover. Cast daily on one spot for a year to make it permanent.","SGEH24",["Druid","Sorcerer","Wizard"]],["Vanishing Step",4,"Conjuration",["Paladin","Ranger"],"Bonus Action","Self","V, S, M","Up to 1 minute",1,0,"","Bonus Action, Concentration, 1 minute. Once per turn, spend 15 ft of movement to teleport 15 ft. Reaction when hit or targeted: teleport 15 ft to make the attack miss or the spell not affect you. Then your Speed drops by 15 ft until the end of your next turn.","SGEH24",["Paladin","Ranger"]],["Void Walk",6,"Transmutation",["Bard","Sorcerer","Warlock","Wizard"],"Action","Touch","V, S","8 hours",0,0,"","Touch, 8 hours. A willing creature gains a Fly Speed equal to its Speed and can hover. +1 target per slot level above 6.","SGEH24",["Bard","Sorcerer","Warlock","Wizard"]],["Wall of Bones",6,"Conjuration",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Up to 10 minutes",1,0,"DEX","Range 60 ft, Concentration, 10 minutes. Wall up to 60 ft long, 10 ft high, 5 ft thick (AC 15, 150 HP). Creatures in its space are pushed out and make a Dexterity save: 4d8 Bludgeoning (half on success). A Magic action spends 20 HP of the wall to summon a Minotaur Skeleton that hunts one target. Max 3.","SGEH24",["Sorcerer","Warlock","Wizard"]],["World Breaker",4,"Evocation",["Druid","Ranger"],"Action","90 ft","V, S","Instantaneous",0,0,"DEX","Range 90 ft. Tear up a 5-ft chunk of terrain and hurl it. It shatters in a 30-ft Cone: Dexterity save or 4d10 Bludgeoning and pushed 15 ft. +1d10 per slot level above 4.","SGEH24",["Druid","Ranger"]]];
var SPF={"Amputate":"Touch, Action. You coat your hand in vicious osteomancy. Make a melee spell attack against a creature within your reach. On a hit it takes 10d8 Slashing damage and you tear off one of its limbs, such as a leg, an arm or a similar appendage.\n\nA creature is immune to the limb loss if it has Immunity to Slashing damage or Legendary Actions, or if the GM rules it too large to lose a limb to this spell. Such a creature instead takes an extra 5d8 Slashing damage.\n\n**Higher-Level Spell Slot.** The first damage increases by 4d8 and the extra damage by 2d8 for each slot level above 7.","Ancestral Bond":"Touch, Action. Material: a Humanoid corpse, which the spell may consume. Ghostly spirits sweep the world and show you the descendants of the Humanoid. You learn how many living relatives it left and whether it has living descendants.\n\n**Amplify.** You can choose one descendant and destroy the corpse to strengthen the magic. That descendant makes a Wisdom save. On a fail you learn its exact location, wherever it is.","Arm Cannon":"Range 30 ft, Action. You shoot the bones of your forearm out through your hand. The wound closes and heals at once. Make a ranged spell attack against a creature in range. On a hit it takes 4d8 Piercing damage and makes a Strength save. On a fail it is pushed 15 feet away from you. If it is pushed into an obstacle, a bone pins it and it has the Restrained condition until the end of its next turn. Creatures that are Large or larger have Advantage on this save.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 and the push distance by 5 feet for each slot level above 2.","Aspect of Death":"Self, Action, Concentration up to 1 minute. Material: the skull of a fallen hero, set with jewels worth at least 4,000 GP. You gather magical threads into the aspect of death, an avatar of bone that surrounds you and fights for you. It is Huge, centered on you and moves with you. No other creature can enter its space. While it is summoned:\n- You count as behind Cover.\n- You have Resistance to all damage.\n- You have Immunity to the Grappled condition.\n- You gain a +1 bonus to spell attack rolls and saving throws.\n- When you cast a spell that deals Bludgeoning, Piercing or Slashing damage, it is cast as if with a spell slot 2 levels higher than the one you spent, to a maximum of level 9.","Astral Barrage":"Range 60 ft, Action, Concentration up to 1 minute. You open a portal to the cosmos and hurl asteroids through it at a creature you can see in range. The target makes a Dexterity save and takes 7d6 Bludgeoning damage on a fail. On each later turn you can take a Magic action to keep the portal open and send the asteroids again. The spell ends if you use your action for anything else. Your Speed is halved until the spell ends.\n\n**Higher-Level Spell Slot.** The damage increases by 2d6 for each slot level above 3.","Bestial Roar":"Self (10-foot Emanation), Action. You let out a monstrous roar that sends shockwaves outward. Each creature in a 10-foot Emanation from you makes a Strength save. On a fail it is pushed 10 feet away from you and has the Prone condition.\n\n**Cantrip Upgrade.** The Emanation grows by 5 feet at levels 5 (15 feet), 11 (20 feet) and 17 (25 feet).","Blind Ambush":"Range 60 ft, Action, 1 minute. Material: a whistle. You blow a whistle with a sound no one can hear. Choose a point on the ground in range. The first time a creature moves 5 feet or more within a 10-foot square centered on that point before the spell ends, an eldritch maw bursts from the ground. It deals 2d10 Piercing damage to each creature in the square and knocks one of them Prone (you choose when it triggers). The spell then ends.\n\n**Higher-Level Spell Slot.** The damage increases by 1d10 for each slot level above 2. With a level 5 or higher slot, the trap can trigger a second time before the spell ends.","Bludgeoning Horror":"Range 15 ft, Action. Material: a body part of a Great One. A mass of tentacles and slugs bursts from your palm. Make a melee spell attack against a creature in range. On a hit it takes 3d6 Bludgeoning damage. On a Critical Hit it also has the Stunned condition until the start of your next turn.\n\n**Higher-Level Spell Slot.** The damage increases by 1d6 and the range by 5 feet for each slot level above 2.","Bone Claws":"Range 30 ft, Bonus Action, Concentration up to 1 minute. Material: a tiger's claw. Choose a creature you can see in range. You fill it with osteomantic energy, and sharp claws grow from its wrist bones. For the duration, the target's Unarmed Strikes deal an extra 1d4 Slashing damage on a hit.\n\n**Higher-Level Spell Slot.** The extra damage is 1d6 with a level 2 slot, 2d4 with level 3, 2d6 with level 4 and 3d4 with level 5 or higher.","Bone Cocoon":"Range 30 ft, Reaction (when you see a creature drop to 0 Hit Points), Concentration up to 1 minute. Material: a shrunken, gilded rib cage worth at least 50 GP. You build a cocoon of cartilage and bone around the creature that fell. While inside, the creature cannot be damaged by attacks or effects from outside the cocoon, has Cover, has the Restrained condition, and makes Death Saving Throws with Advantage.\n\n**The cocoon.** It has 25 Hit Points and an AC of 11 plus your spellcasting ability modifier. It has Resistance to Cold, Fire and Necrotic damage and Immunity to Poison and Psychic damage. If you lose Concentration or it drops to 0 Hit Points, it is destroyed and the spell ends.\n\n**Higher-Level Spell Slot.** The cocoon's Hit Points increase by 25 for each slot level above 2.","Bone Shield":"Self, Reaction. A barrier of long thigh bones rises to guard you. You reduce the damage you are about to take by 1d12. If the attacker is within 10 feet of you, the bone barrier bursts and deals Slashing damage to it equal to the amount you reduced.\n\n**Higher-Level Spell Slot.** The reduction increases by 1d12 for each slot level above 1.","Boneyard":"Touch, 24 hours, until dispelled. Material: enchanted bones, incense and herbs worth at least 1,000 GP, which the spell consumes. You touch a point and fill a Sphere around it with osteomancy. The Sphere has a radius of up to 120 feet. The spell fails if the area is already under a Boneyard or Hallow spell. In the area:\n\n**Dead Man's Tale.** You know the exact location of every Undead in the area, hear its thoughts if it has any, and know whether anyone controls it.\n\n**Early Grave.** Creatures in the area lose Resistance and Immunity to Necrotic and Piercing damage.\n\n**Funeral March.** You can use a Reaction whenever a non-Undead creature dies in the area to pull its skeleton from its flesh and make it rise under your control. It returns with 1 Hit Point, its creature type becomes Undead, it has Immunity to all damage, and it loses any Legendary Actions. It acts right after you and you command it mentally. At the end of its next turn it dies, and only a Wish spell can resurrect it.","Brittle Bone Throw":"Range 60 ft, Action. Material: bone powder. You hurl a splinter of bone at a creature in range. Make a ranged spell attack. On a hit the target takes 1d8 Piercing damage.\n\n**Ricochet.** On a miss, you can shatter the bone in flight and send the fragment at a different creature within 30 feet of the original target. Make another ranged spell attack. On a hit that creature takes 1d4 Piercing damage.\n\n**Cantrip Upgrade.** Both damage dice rise at levels 5 (2d8 and 2d4), 11 (3d8 and 3d4) and 17 (4d8 and 4d4).","Bury":"Range 120 ft, Action, Concentration up to 10 minutes. You greatly strengthen gravity in a Cylinder 30 feet in radius and 300 feet high, centered on a point on the ground in range.\n\n**Crushing weight.** Creatures in the area have the Prone condition and cannot lose it while there. A creature that enters the area for the first time on a turn or starts its turn there is Prone and takes 4d6 Bludgeoning damage. A flying creature in the area falls to the ground at once and is Prone. A creature must succeed on a Strength save to move or take any action. Each foot of movement costs 3 extra feet.\n\n**Pressed into the ground.** A Prone creature that ends its turn in the Cylinder makes a Strength save or is forced into the ground. It then has the Restrained and Incapacitated conditions and gains Cover, with only its upper body visible. It repeats the save at the end of each of its turns and frees itself on a success.\n\n**Cracked ground.** If the spell lasts its full duration, the ground cracks under the weight and becomes Difficult Terrain. Clearing each 5-foot square by hand takes at least 1 minute.","Calcified Memories":"Touch, Action. You touch the bones of a dead creature. A gray ghostly image of it appears over the corpse and replays the last 6 seconds of its life. The image shows only the creature's own actions, such as recoiling from an unseen monster or choking on poison gas. The thing that caused them is shown only as an outline.\n\nThe spell has no effect on Undead creatures. Once a corpse's death has been shown this way, it cannot be shown again for 24 hours.","Chisel Skull":"Range 60 ft, Action, no Verbal component. Material: a piece of skull bone. Choose a creature you can see in range. Its skull cracks and splinters inward. The creature makes a Constitution save. On a fail it takes 8d10 Piercing damage and has the Paralyzed condition until the end of its next turn. On a success it takes half as much damage only. A creature without a skull is immune.","Cosmic Eye":"Range 150 ft, Action. Material: an eldritch parasite. Your eye turns into an endless starry sky and fires a bolt of eldritch energy. Make a ranged spell attack against a creature in range. On a hit the target takes 1d8 Necrotic damage. On a Critical Hit, you treat any damage die that rolled 4 or lower as a 5.\n\n**Cantrip Upgrade.** The damage becomes 2d8 at level 5, 3d8 at level 11 and 4d8 at level 17.","Crush":"Range 60 ft, Action. Material: bone powder. You try to trap a creature you can see in range in a field of gravity that folds in on itself. The target makes a Strength save. On a fail it takes 12d10 Bludgeoning damage and has the Stunned condition until the start of your next turn from the pain.\n\n**Higher-Level Spell Slot.** You can target one more creature for each slot level above 7.","Dampen Gravity":"Self (60-foot Emanation), Action, 1 hour. Material: a feather. You weaken the pull of gravity in a 60-foot Emanation around you. Each creature you choose in the area has its jump distance doubled and its Speed increased by 10 feet. An affected creature also has Advantage on Dexterity (Acrobatics) checks and takes no damage from falling if it ends its fall within the Emanation.","Displacing Maw":"Range 10 ft, Action. Your rib cage opens up into a hungry maw that tries to swallow a creature in range. The creature makes a Strength save. On a fail it takes 4d8 Piercing damage and is carried by magic to a point on the ground that you choose within 60 feet of you, where the maw spits it out. On a success it takes half as much damage only.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 and the maximum teleport distance by 10 feet for each slot level above 3.","Divine Order: Reveal":"Range 30 ft, Bonus Action. You try to look at the soul of a creature in range. The creature makes a Charisma save. On a fail its origins are revealed to you. You learn its alignment, creature type, all ability scores, saving throw proficiencies, skill proficiencies, weapon proficiencies, armor training, senses, languages, Vulnerabilities, Resistances, Immunities, Challenge Rating and traits. On a success, it is immune to this spell for the next 24 hours.\n\n**GM note.** This shows the top part of a stat block (everything above the actions).","Divine Order: Sacrifice":"Range 120 ft, Action, Concentration up to 1 minute. You tear open a crack in the world and let the will of a Great One crush a creature of your choice in range. The contact with the eldritch being deals 8d6 Psychic damage to the target, which then makes a Charisma save.\n\n**Failed save.** The target is pulled through the tear into the cosmos. While there, it has the Incapacitated condition. At the start of each of its turns there, it takes 3d6 Cold damage plus 3d6 Psychic damage and must succeed on a DC 20 Intelligence save or gain a Short-Term Madness. If it is still alive when the spell ends, it returns to the space it left, or the nearest free space. If it is killed in the void, its corpse never returns. A body lost this way can never be recovered, not even by Wish.\n\n**Successful save.** The target gains a Long-Term Madness and the spell ends.\n\n**Your risk.** If your Concentration ends early, you must succeed on a DC 20 Intelligence save or gain a Long-Term Madness as the whispers turn on your mind. When the spell ends, roll a d100. On a 1, the breach does not close and only widens, and it threatens to swallow the whole world.","Divine Order: Transcend":"Self, Action, Concentration up to 1 minute. You call on the Great Ones for guidance. Until the spell ends, you can cast any Warlock spell of level 5 or lower without a spell slot and without preparing it. As part of casting this spell, you can cast one spell with a casting time of an action from that list.\n\n**The price.** At the end of each of your turns, you make a DC 18 Intelligence save or take 2d10 Psychic damage. If you fail this save twice, the spell ends early and you gain a Short-Term Madness.\n\n**Higher-Level Spell Slot.** If you cast it with a level 9 slot, it does not require Concentration. You can end it early with no action.","Dread Scarecrow":"Self (30-foot Emanation), Action, Concentration up to 1 minute. Material: a flute made of a femur worth at least 50 GP. You create the illusion that every bone in your body breaks and bends the wrong way, with the sound of a skull cracking. Each creature you choose in a 30-foot Emanation from you makes a Wisdom save. On a fail it has the Frightened condition for the duration. While Frightened this way, its Speed is 0 and it has the Prone condition, because its legs give out in fear. If an affected creature takes damage, it repeats the save at the end of its next turn and ends the effect on itself on a success.","Electrify":"Self, Bonus Action, 1 round. Lightning gathers in your hands. The next time you hit a creature with a melee attack roll, including a melee spell attack, before the start of your next turn, the target takes 1d12 Lightning damage and makes a Constitution save. On a fail it has the Stunned condition until the start of its next turn.\n\n**Higher-Level Spell Slot.** The damage increases by 1d12 for each slot level above 1.","Erupting Lightning":"Range 120 ft, Action. Material: the vertebrae of a Lightning Vessel barbarian. You slam your palm into the ground and pillars of lightning burst up under your foes. The area is up to seven 5-foot Cubes arranged as you like, and each Cube must share at least one face with another Cube. Each creature in the area makes a Dexterity save. On a fail it takes 7d10 Lightning damage and has the Prone condition. On a success it takes half as much damage only.\n\n**Higher-Level Spell Slot.** You create two more 5-foot Cubes of lightning for each slot level above 6.","Fall":"Self, Action. Material: an elastic band. You shift the direction of gravity for yourself and immediately fall 200 feet in a direction you choose. If you strike a solid surface, you take fall damage based on the distance you traveled.\n\n**Higher-Level Spell Slot.** The distance you fall increases by 50 feet for each slot level above 1.","Fling":"Touch, Action. You flick a finger against a creature and it is hit by a crushing gravitational force. It makes a Strength save. On a fail it takes 6d10 Bludgeoning damage and is pushed 120 feet away from you. The push stops early if the creature hits a solid surface or is pushed into a creature of its size or larger. On a success it takes half as much damage and is not pushed.\n\n**Collisions.** If the target is pushed into or through another creature's space, that creature makes a Dexterity save and takes 1d10 Bludgeoning damage on a fail or half as much on a success. This damage rises by 1d10 for each size category the struck creature is smaller than the target.\n\n**Higher-Level Spell Slot.** The damage to the target increases by 1d10 and the push distance by 30 feet for each slot level above 4.","Forest of Dread":"Self (30-foot-radius Cylinder), Action, Concentration up to 10 minutes. You touch the ground and tree-shaped bones burst out of it in a Cylinder 30 feet in radius and 20 feet high, centered on you. Each creature of your choice in the area makes a Dexterity save. On a fail it takes 4d8 Piercing damage, or half as much on a success.\n\n**Lasting area.** For the duration, the area is Difficult Terrain. A creature that moves into or within it takes 2d8 Piercing damage for every 5 feet it travels. You are immune to this damage. The forest gives Cover to creatures inside it. The bones crumble away when the spell ends.","Fractured Shell":"Touch, Action, Concentration up to 10 minutes. Material: a porcupine's carapace. Spiked plates of bone push out through the skin of a willing creature you touch. It takes 1 Piercing damage. For the duration, the first time each turn a melee attack roll hits the target, the attacker takes 2d4 Piercing damage.\n\n**Higher-Level Spell Slot.** The damage to the attacker increases by 2d4 for each slot level above 1. With a level 5 or higher slot, the spell no longer needs Concentration and lasts 10 minutes.","Gravitational Distortion":"Range 60 ft, Action. Reality twists in a 30-foot-radius Sphere centered on a point you can see in range. Each creature in the area makes a Strength save. On a fail it takes 6d6 Bludgeoning damage and is pushed 30 feet in a straight line in a direction you choose. On a success it takes half as much damage and is not pushed.\n\n**Higher-Level Spell Slot.** The damage increases by 1d6 for each slot level above 4.","Graviturgic Smite":"Self, Bonus Action, Concentration up to 1 minute. You call on energy taken from black holes. The next time you hit a creature with a weapon attack before the spell ends, the attack deals an extra 3d4 Bludgeoning damage and the target makes a Strength save.\n\n**Failed save.** The target's Speed is reduced to 10 feet until the spell ends.\n\n**Successful save.** Its Speed is reduced by 10 feet until the spell ends, to a minimum of 10 feet.\n\n**Higher-Level Spell Slot.** The damage increases by 2d4 for each slot level above 2.","Gravity Barrier":"Range 60 ft, Action, Concentration up to 10 minutes. You raise a wall of intense gravity on the ground at a point you can see in range. It can be a straight wall up to 30 feet long, 10 feet high and 1 foot thick, or a ring up to 20 feet across, 20 feet high and 1 foot thick. Its space is Difficult Terrain. Ranged weapon attacks that pass through it automatically fail, and other ranged attack rolls through it have Disadvantage.\n\nA creature that passes through the wall's space makes a Strength save. On a fail it takes 4d8 Bludgeoning damage, has the Prone condition and its Speed becomes 0 until the end of its turn.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 for each slot level above 4.","Gravity Leap":"Self, Action, 1 minute. You strengthen the gravitational field around your body so you can leap higher and farther. For the duration, your jump distance is tripled.\n\n**Gravity wave.** Once per turn, right after you jump, a wave of gravity bursts out. Each creature within 5 feet of the space you left makes a Strength save. On a fail it has the Prone condition.","Gravity Spike":"Range 60 ft, Action. A pocket of shifting gravity throws up a spike of ground. Choose a creature standing on the ground that you can see in range. It makes a Dexterity save. On a fail it takes 1d6 Piercing damage and has the Prone condition. On a success it takes half as much damage only.\n\n**Cantrip Upgrade.** The damage becomes 2d6 at level 5, 3d6 at level 11 and 4d6 at level 17.","Gravity Storm":"Range 120 ft, Action, 2 rounds. A pocket of gravity breaks into waves. Choose a point you can see in range. When you cast the spell and at the start of each of your later turns for the duration, each creature in a 20-foot Sphere centered on that point makes a Dexterity save. On a fail it takes 2d6 Bludgeoning damage and has the Prone condition. On a success it takes half as much damage only.\n\n**Higher-Level Spell Slot.** The damage increases by 2d6, the Sphere's radius by 5 feet and the duration by 1 round for each slot level above 2.","Gravity Well (Steinhardt)":"Range 60 ft, Action. You fire a projectile of compressed gravitational force at a creature you can see in range. Make a ranged spell attack. On a hit the target takes 2d8 Force damage and is pulled 20 feet in a straight line toward you.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 for each slot level above 1.","Gravity Whip":"Range 10 ft, Action. You lash out with a twist of gravity from your palm. Make a melee spell attack against a creature within 10 feet of you. On a hit the target takes 1d4 Bludgeoning damage and is pushed 5 feet in a straight line in a direction you choose. Its Speed is also reduced by 10 feet until the start of your next turn.\n\n**Cantrip Upgrade.** At level 5 the damage is 2d4 and the push is 10 feet. At level 11 it is 3d4 and 15 feet. At level 17 it is 4d4 and 20 feet.","Jumping Jolt":"Range 60 ft, Action. You loose an arc of lightning at a creature in range. Make a ranged spell attack. On a hit the target takes 4d12 Lightning damage. On a miss it takes half as much damage only. Either way you can make the spell jump to another creature within 20 feet of the target. Make a new ranged spell attack against that creature, with the same hit and miss results. The spell cannot hit the same creature twice or jump to a creature outside the spell's range. It can jump up to four times.\n\n**Higher-Level Spell Slot.** The damage increases by 1d12 and the number of jumps by one for each slot level above 4.","Lightning Charged":"Touch, Action, 10 minutes. Material: a piece of metal once used in a lightning rod. You pour lightning into a creature. It is harmless to the creature but leaks out in dangerous bursts to those near it. Each time the charged creature affects another creature with a spell of Touch range, hits another creature with a melee attack roll, or ends its turn grappling or Grappled by another creature, the other creature takes 1d6 Lightning damage. After the spell has discharged 6 times (up to 6d6 Lightning damage), it ends.\n\n**Higher-Level Spell Slot.** For each slot level above 2, the spell can discharge 2 more times (up to 2d6 more total damage) before it ends.","Maiden of Bones":"Range 60 ft, Action, 1 minute. Material: a virgin's carpal bone. A creature you choose in range makes a Strength save. On a fail an iron maiden made of bone forms around it in its space. The target has the Incapacitated and Restrained conditions, has Cover, cannot be damaged by attacks or effects from outside the maiden, and takes 3d6 Piercing damage at the start of each of its turns as bone spikes stab it. At the end of each of its turns, the trapped creature repeats the save and, on a success, escapes and ends the spell.\n\n**The maiden.** It has AC equal to 10 plus your spellcasting modifier, 80 Hit Points, Immunity to Psychic and Poison damage and Vulnerability to Bludgeoning damage. If it is destroyed, the trapped creature is freed and the spell ends.\n\n**Higher-Level Spell Slot.** The damage increases by 1d6 and the maiden's Hit Points by 20 for each slot level above 4.","Malicious Rancor":"Range 60 ft, Action, 1 round. Material: a skull of a creature that died under a curse, worth at least 1 SP, which the spell consumes. You throw a scratched, cursed skull at a creature in range, and it bursts with hatred. Make a ranged spell attack. On a hit the target takes 1d10 Necrotic damage.\n\n**Wail.** Hit or miss, the skull then detonates with a psychic wail. The target and each creature in a 10-foot-radius Sphere centered on it make a Wisdom save, taking 5d4 Psychic damage on a fail or half as much on a success. Until the start of your next turn, any creature that enters the Sphere or ends its turn there makes the same save. A creature makes this save only once per turn.\n\n**Higher-Level Spell Slot.** The Psychic damage increases by 2d4 for each slot level above 3.","Marrow Transplant":"Range 30 ft, Action. Material: a piece of spinal bone and a diamond worth at least 300 GP, which the spell consumes. You drain a creature's bone marrow and move its life force into another creature. Make a ranged spell attack against a creature in range. On a hit it takes 4d6 Necrotic damage. Choose another creature in range. It regains Hit Points equal to the damage dealt. If it died less than 1 minute ago, it comes back to life with that many Hit Points instead.\n\nIf any target lacks bones, the spell fails. It cannot bring back a creature that died of old age or restore missing body parts.\n\n**Higher-Level Spell Slot.** The damage increases by 1d6 for each slot level above 4.","Osseous Cage":"Self (10-foot-radius Sphere), Action, 10 minutes. Cartilage and bone rise from the ground and form a cage around a 10-foot-radius Sphere centered on you. The bones give Three-Quarters Cover to creatures both inside and outside. No creature, you included, can pass through the cage unless you take a Reaction to let one cross as it tries. A Large or larger creature cannot enter and is pushed to the nearest free space if it is inside the area when the cage appears.\n\n**The cage.** It has AC 12, 100 Hit Points and Vulnerability to Bludgeoning damage. If you cast the spell again while a cage is up, the old cage turns to dust.\n\n**Higher-Level Spell Slot.** The cage has an extra 20 Hit Points for each slot level above 3.","Osseous Impalement":"Range 60 ft, Action, Concentration up to 1 minute. Material: a calcified bamboo stick. Huge bone spikes burst from the ground under up to four creatures standing on the ground that you can see in range. Each makes a Dexterity save. On a fail it takes 3d10 Piercing damage and is impaled for the duration. An impaled creature is held 5 feet in the air, has the Restrained condition and takes 1d10 Piercing damage at the start of each of its turns. It can take an action to make a Strength (Athletics) check against your spell save DC. On a success it breaks the spike and ends the effect on itself.\n\n**Higher-Level Spell Slot.** Both the first and the ongoing damage increase by 1d10 for each slot level above 3.","Osteophagia":"Touch, Action. This is the deadliest osteomantic power. You liquefy a creature's skeleton in seconds and its body collapses in on itself. Choose a creature within your reach. It makes a Constitution save. On a fail it dies. On a success it takes 10d6 Necrotic damage.\n\nA creature is immune if it has no bones, or if its Challenge Rating or character level is equal to or higher than your own Challenge Rating or character level.","Otherworldly Gaze":"Self, Action, 10 minutes. You draw on eldritch forces and your eyes turn black, letting you see past the veil of reality. For the duration:\n- You have Advantage on Wisdom (Perception) checks.\n- You sense eldritch creatures within 120 feet of you, including Aberrations, Celestials and Fiends.\n- You see the true form of any shapechanger or creature transformed by magic within 30 feet of you.\n- If you have the Blinded condition, you ignore its effects while the spell lasts.","Phalangeal Shot":"Self (30-foot Line), Action. You point your fingers and fire your finger bones down a Line 30 feet long and 1 foot wide, like gun shots. They regrow at once and leave your hand unharmed. Each creature in the Line makes a Dexterity save. On a fail it takes 2d8 Piercing damage.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 for each slot level above 1.","Pressure Cage":"Range 60 ft, Action, Concentration up to 1 minute. Material: a shard of ball and chain. Gravity grows heavy in a 10-foot-radius Sphere centered on a point you choose in range. The area is Difficult Terrain. When a creature enters the Sphere for the first time on a turn or starts its turn there, it makes a Strength save. On a fail its Speed is reduced to 0 until the start of its next turn. On your later turns, you can take a Bonus Action to move the Sphere up to 20 feet in any direction.\n\n**Higher-Level Spell Slot.** The Sphere's radius increases by 5 feet for each slot level above 2.","Radiant Bell":"Self, Action. Material: a silvered choir bell worth at least 5 GP, which the spell consumes. You ring a silver bell filled with healing magic. Choose any number of creatures within 30 feet of you. For each one, you can end one of these conditions on it: Charmed, Frightened, Poisoned, Petrified or Stunned. The cure does not work on a target that has the Deafened condition.","Radiant Slaughter":"Self (30-foot Emanation), Action. Material: the petrified fetus of a Great One. You release a small nova of eldritch power, a secret technique of the Obitus Scholare. Each creature in a 30-foot Emanation from you makes a Dexterity save. On a fail it takes 2d6 Force damage plus 3d6 Radiant damage and has the Prone condition. On a success it takes half as much damage only. Creatures within 5 feet of you make the save with Disadvantage.\n\n**Higher-Level Spell Slot.** The Force and the Radiant damage each increase by 1d6 for each slot level above 3.","Rolling Bones":"Self, 1 minute. Material: the bones of a small mammal worth at least 1 GP. You cast the bones and let fate give you an omen. Roll 1d6.\n\n**5 or 6.** You learn whether you are not likely, likely or very likely to meet Hostile creatures in the next hour. You also learn the creature type you are most likely to meet.\n\n**2, 3 or 4.** You learn only how likely you are to meet Hostile creatures in the next hour.\n\n**1.** The Material components are consumed and you take 1 Psychic damage as fate pushes back. You learn nothing and cannot cast the spell again until you finish a Short Rest.\n\n**Repeated casting.** If you cast the spell two or more times before a Long Rest, each casting after the first has a cumulative 25 percent chance of a false reading. The GM rolls this in secret.","Rubber Bones":"Touch, Action, Concentration up to 10 minutes. A willing creature you touch has soft, rubbery bones. For the duration it:\n- Can spend 5 feet of movement to end the Grappled condition on itself with no ability check.\n- Can squeeze through a space meant for a creature two sizes smaller.\n- Has Advantage on Dexterity saving throws.\n- Has Resistance to Bludgeoning damage.\n- Has its reach with melee attacks increased by 5 feet.\n\n**Higher-Level Spell Slot.** You can target one more creature for each slot level above 3.","Rupturing Curse":"Range 60 ft, Action, Concentration up to 1 minute. You focus magic to break a foe's body. Choose a creature you can see in range. It makes a Constitution save. On a fail it takes 3d10 Piercing damage and has the Prone condition.\n\n**Shattered skeleton.** If the target takes Bludgeoning damage equal to 5 times its Constitution modifier (minimum 5) or more in a single turn, its skeleton breaks and its Speed is 0 for the duration. If it does not take that much damage before the start of its next turn, the spell ends. A creature without bones is immune to this effect.\n\n**Higher-Level Spell Slot.** The damage increases by 1d10 for each slot level above 2.","Silvered Shell":"Self, Bonus Action, 1 minute. Material: an empty phantasm shell, which the spell does not consume. You touch a weapon and coat it in otherworldly bile. For the duration it counts as Moongilded, and while you hold it, it deals an extra 1d4 Force damage on a hit.\n\n**Higher-Level Spell Slot.** The duration is 10 minutes with a level 2 slot, 1 hour with level 3, 8 hours with level 4 and 24 hours with level 5 or higher.","Skeletal Tail":"Self (15-foot Emanation), Bonus Action, 1 minute. Material: a scorpion's tail. You grow a long, scorpion-like tail of sharp bone. Whenever a creature moves into or within a 15-foot Emanation from you, you can take a Reaction to try to pierce it with the tail. Make a melee spell attack against the creature. On a hit it takes Piercing damage equal to 2d4 plus your spellcasting modifier, and the tail drags it to the nearest unoccupied space next to you.\n\n**Higher-Level Spell Slot.** The damage increases by 2d4 for each slot level above 2.","Spectral Fury":"Range 30 ft, Action. Material: a melee weapon worth at least 1 SP. You send out three spectral doubles of yourself to cut down enemies within 30 feet. They can strike one target or several. Make one melee spell attack for each double. On a hit the target takes 4d8 damage of the type the cast weapon deals.\n\n**Follow-up.** You can then take a Bonus Action to move up to 30 feet in a straight line toward one of the targets without provoking Opportunity Attacks, leaving a spectral trail, and make one melee attack with a weapon.\n\n**Higher-Level Spell Slot.** Each double's damage increases by 2d8 for each slot level above 3.","Spectral Slash":"Range 20 ft, Bonus Action. Material: a melee weapon worth at least 1 SP. A spectral double of you cuts down a foe. Make a melee spell attack against a creature within 20 feet of you. On a hit it takes 1d8 damage of the type your weapon deals.\n\n**Follow-up.** You can then take a Magic action to move up to 20 feet in a straight line toward the target, leaving a spectral trail, and take the Attack action against it with the weapon used to cast the spell.\n\n**Higher-Level Spell Slot.** The damage increases by 1d8 and the movement distance by 10 feet for each slot level above 1.","Starfall":"Self (30-foot Emanation), Bonus Action, Concentration up to 1 minute. You call down a storm of stars. When you cast the spell, and as a Bonus Action on each of your later turns, you can drop stars on creatures of your choice in a 30-foot Emanation centered on you. Each creature a star hits takes 3d4 Radiant damage.\n\n**Higher-Level Spell Slot.** The damage increases by 1d4 for each slot level above 5.","Unbound Chamber":"Range 500 ft, 1 minute, 8 hours. In an ancient ritual, you warp gravity within an enclosed space of your choice in range. The chamber can be any shape up to 200 feet wide, 200 feet high and 200 feet long. While inside, a creature takes no damage from falling, has its jump distance tripled, has a Fly Speed equal to its Speed and can hover. If you cast the spell on the same spot every day for a year, the effect becomes permanent.","Vanishing Step":"Self, Bonus Action, Concentration up to 1 minute. Material: the bone of an old hunter. For the duration, once on each of your turns you can spend 15 feet of movement to teleport to an unoccupied space you can see within 15 feet. You cannot do this while Prone or Incapacitated.\n\n**Reaction.** When an attack hits you or a spell targets you, you can take a Reaction to teleport to an unoccupied space you can see within 15 feet. The attack misses, or the spell does not affect you if you left its range or area. After doing so, your Speed is reduced by 15 feet until the end of your next turn.","Void Walk":"Touch, Action, 8 hours. A willing creature you touch gains a Fly Speed equal to its Speed and can hover for the duration.\n\n**Higher-Level Spell Slot.** You can target one more creature for each slot level above 6.","Wall of Bones":"Range 60 ft, Action, Concentration up to 10 minutes. Material: a calcified egg shell. A wall of broken bones rises at a point you choose in range. It can lie in any orientation, horizontal, vertical or diagonal, but must rest on a solid surface. It is up to 60 feet long, 10 feet high and 5 feet thick. It blocks line of sight and creatures cannot pass through it. It is an object with AC 15, 150 Hit Points, Immunity to Poison and Psychic damage and Vulnerability to Bludgeoning damage. At 0 Hit Points it is destroyed.\n\n**Appearing.** Each creature in the wall's space is pushed out by the shortest route and makes a Dexterity save. On a fail it takes 4d8 Bludgeoning damage, or half as much on a success.\n\n**Minotaur Skeletons.** While the wall has enough Hit Points, you can take a Magic action to give up 20 Hit Points of the wall and summon a Minotaur Skeleton with murderous intent. It appears in an unoccupied space of your choice next to the wall. Name one creature you can see within 60 feet of it, which becomes the skeleton's only enemy. The skeleton acts right after you, ignores your orders, tries to kill its target by any means and has Immunity to the Charmed condition. When its target dies, it falls to dust. You can have at most three such creatures at once.","World Breaker":"Range 90 ft, Action. You rip a 5-foot by 5-foot piece of nonmagical terrain from the ground and throw it at a point you can see in range. It shatters in a 30-foot Cone extending away from you. Each creature in the area makes a Dexterity save. On a fail it takes 4d10 Bludgeoning damage and is pushed 15 feet away from you.\n\n**Higher-Level Spell Slot.** The damage increases by 1d10 for each slot level above 4."};
var IT=[["Bag of Cannonballs","Wondrous Item","Uncommon",0,"A bag linked to an extradimensional space that never weighs more than 3 lb. It holds up to 100 Cannonballs or similar objects. You draw them out as from a plain sack, with no action.",{}],["Damascena","Wondrous Item","Uncommon",0,"A Scion device that burns lead bullets into blue flame that scorches the abhorrent. Magic action: project a 15-ft Cone of blue fire. Each creature in it makes a Dexterity save (DC 11 plus your Proficiency Bonus) and takes 4d4 Fire damage plus a number of d4s equal to your Proficiency Bonus on a fail, or half as much on a success. Each use consumes 5 Bullets.",{}],["Hand of Glory","Wondrous Item","Very Rare",0,"The hand of a hanged scourgeborne, waxed and fermented in a casket. While you hold it, you can attune to one more magic item, and that item must be a ring worn on the hand. It has 5 charges and regains 1 at dusk. Each time you spend a charge, one finger burns down to a stump. Magic action while holding it: spend 1 charge to light a finger and cast Invisibility on yourself. For the duration the hand sheds Bright Light in a 10-ft radius that only you can see, and the spell ends early if you snuff the flame (no action). While Invisible this way, you can cast Knock at will on objects within the Bright Light.",{"ch":[5,"1","dusk"]}],["Sanctified Cannon","Weapon","Uncommon",0,"A Cannon (3d10 Bludgeoning, range 120/240 ft, Artillery, Booming, Two-Handed, Push mastery, uses Cannonballs). **Charged Shot.** Once on each of your turns when you take the Attack action, you can replace one Cannon attack with a charged shot. Each creature in a 120-ft-long, 5-ft-wide Line in front of you makes a Dexterity save (DC 8 plus your Strength modifier plus your Proficiency Bonus) or takes 3d12 Bludgeoning damage and has the Prone condition. You can do this only if you have not moved this turn, and your Speed is 0 until the end of the turn after you do.",{"base":["Cannon"],"wp":{"d":"3d10","t":"Bludgeoning","cat":"M","k":"R","p":"Two-Handed","m":"Push","w":90,"r":"120/240","xw":1}}],["Big Bertha","Weapon","Rare",0,"A Cannon inlaid with moongold (3d10 Bludgeoning, range 120/240 ft, Artillery, Booming, Two-Handed, Push mastery, uses Cannonballs). You gain a +1 bonus to attack and damage rolls with it. It deals an extra 1d4 Bludgeoning damage to non-Humanoid creatures. Moongold guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. **Infusion.** As a Bonus Action, turn the dials to charge your loaded ammo. Your next attack gains one benefit. Forceful: On a hit the target takes an extra 1d6 Bludgeoning damage and makes a DC 15 Strength save or is pushed 15 ft and knocked Prone. Or fire at your own feet while on solid ground to blast yourself up and land in a space of your choice within 30 ft of the blast. Incendiary: On a hit the target takes an extra 3d4 Fire damage. Unstable: On a hit the target takes an extra 1d8 Cold damage, and a 10-ft Emanation around it fills with arcane mist that is Difficult Terrain for 1 minute.",{"fx":{"atk":1,"dmg":1},"base":["Cannon"],"xd":["Non-Humanoid: +1d4 Bludgeoning"],"wp":{"d":"3d10","t":"Bludgeoning","cat":"M","k":"R","p":"Two-Handed","m":"Push","w":90,"r":"120/240","xw":1}}],["Moongold Weapon","Weapon","Unknown",0,"Any weapon except a Net, magic or not, can be moongilded. Moongold adds 1d4 to damage rolls against non-Humanoid creatures. It guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. Moongilding one weapon costs 1000 gp more than the base price and covers the metal and the time and skill to plate it without dulling the weapon. The coating wears off if the weapon is not recoated within 3 months, ending its effects. Recoating before then costs 500 gp and resets the 3 months.",{"xd":["Non-Humanoid: +1d4"]}],["Moongold Ammunition","Weapon","Unknown",0,"Any ammunition except an Energy Cell can be moongilded. Moongold adds 1d4 to damage rolls against non-Humanoid creatures. It guides in the dark, so creatures holding or wearing it have Advantage on saves against the Frightened condition and against Madness. Moongilding ten pieces of ammunition costs 1000 gp more than the base price. The coating wears off if the ammunition is not recoated within 3 months, ending its effects. Recoating before then costs 500 gp and resets the 3 months.",{"xd":["Non-Humanoid: +1d4"]}]];
var ISP={"Hand of Glory":{"sp":[["Invisibility",2],["Knock",2]]}};
