var GR=[["Bullet",0.2,0.1,"Ammunition","Ammunition for Barrel firearms (Blunderbuss, Flintlock, Pistol, Rifle). Destroyed when used."],["Bullets (10)",2,1,"Ammunition","Ten Bullets. Ammunition for Barrel firearms. Destroyed when used."],["Cannonball",3,9,"Ammunition","Ammunition for the Cannon. Destroyed when used."],["Explosive Bullet",4,0.1,"Ammunition","A creature hit takes the weapon's normal damage, and each creature within 5 ft of it makes a Dexterity save (DC 8 plus the ability modifier of the attack roll plus your Proficiency Bonus) or takes 1d8 Fire damage. On a miss, it fails to detonate. Destroyed once it hits."],["Explosive Bullets (10)",40,1,"Ammunition","Ten Explosive Bullets. A creature hit takes the weapon's normal damage, and each creature within 5 ft of it makes a Dexterity save (DC 8 plus the ability modifier of the attack roll plus your Proficiency Bonus) or takes 1d8 Fire damage. On a miss, it fails to detonate. Destroyed once it hits."],["Explosive Cannonball",30,12,"Ammunition","A creature hit takes the weapon's normal damage, and each creature within 10 ft of it makes a Dexterity save (DC 8 plus your Strength modifier plus your Proficiency Bonus) or takes 2d8 Fire damage. On a miss, it fails to detonate. Destroyed once it hits."],["Scatter Bullet",1.5,0.1,"Ammunition","Fired from a weapon with Spread Fire, you can choose to ignore Spread Fire and make an attack roll instead. On a hit the target takes the weapon's normal damage and the bullet bursts into shrapnel in a 15-ft Cone starting at the target and pointing away from you. Each creature in the Cone makes a Dexterity save (DC 8 plus your Dexterity modifier plus your Proficiency Bonus) and takes damage equal to your weapon damage on a fail. Destroyed once it hits."],["Scatter Bullets (10)",15,1,"Ammunition","Ten Scatter Bullets. Fired from a weapon with Spread Fire, you can choose to ignore Spread Fire and make an attack roll instead. On a hit the target takes the weapon's normal damage and the bullet bursts into shrapnel in a 15-ft Cone starting at the target and pointing away from you. Each creature in the Cone makes a Dexterity save (DC 8 plus your Dexterity modifier plus your Proficiency Bonus) and takes damage equal to your weapon damage on a fail. Destroyed once it hits."]];
var WPW={"Cleaver":{"o":{"d":"1d8","t":"Slashing","cat":"M","k":"M","p":"Heavy, Versatile (1d12)","m":"Graze","w":4,"tp":"tsgeh"},"c":15.0,"t":""},"Scythe":{"o":{"d":"1d10","t":"Slashing","cat":"M","k":"M","p":"Finesse, Reach, Two-Handed","m":"Cleave","w":6,"tp":"tsgeh"},"c":20.0,"t":""},"Blunderbuss":{"o":{"d":"2d4","t":"Piercing","cat":"S","k":"R","p":"Ammunition, Barrel, Blaring, Spread Fire, Twinned Barrel, Two-Handed","m":"Topple","w":10,"tp":"tsgeh","r":"20"},"c":30.0,"t":"Barrel (2) and Twinned Barrel: two barrels, fired one at a time or both as one attack that raises the damage die one step. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Spread Fire: no normal attack, it sprays a 20 ft Cone and each creature makes a Dexterity save (DC 8 plus Dexterity modifier plus Proficiency Bonus) or takes the weapon's damage. Ammo: Bullet."},"Flintlock":{"o":{"d":"1d8","t":"Piercing","cat":"S","k":"R","p":"Ammunition, Barrel, Blaring, Light","m":"Sap","w":3,"tp":"tsgeh","r":"100/320"},"c":10.0,"t":"Barrel (1): reload as an action, as part of the Attack action in place of an attack, or as a Bonus Action since it is Light. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet."},"Cannon":{"o":{"d":"3d10","t":"Bludgeoning","cat":"M","k":"R","p":"Artillery, Booming, Two-Handed","m":"Push","w":90,"tp":"tsgeh","r":"120/240"},"c":500.0,"t":"Artillery: use Strength for attack and damage rolls, and it needs ammunition. Reload takes an action. After a fight, spend 1 minute to recover half the ammo you used (round down). Booming: heard 500 ft away, you automatically fail Stealth to Hide until your next turn, and creatures in the sound have automatic success on Perception checks against you. Ammo: Cannonball."},"Pistol":{"o":{"d":"1d6","t":"Piercing","cat":"M","k":"R","p":"Ammunition, Barrel, Blaring, Fan Fire","m":"Vex","w":3,"tp":"tsgeh","r":"40/120"},"c":15.0,"t":"Barrel (6) and Fan Fire: as an action fire a number of bullets equal to your Dexterity modifier (min 2, up to the barrel), each shot after the first at a cumulative -3 and with no modifier added to damage. Your Speed is 0 until the end of your turn and long-range shots miss. A 1 jams the weapon (DC 15 Dexterity (Sleight of Hand) as an action or 1 hour of mending, a failure breaks it). Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet."},"Rifle":{"o":{"d":"1d10","t":"Piercing","cat":"M","k":"R","p":"Ammunition, Barrel, Blaring, Steady, Twinned Barrel, Two-Handed","m":"Slow","w":8,"tp":"tsgeh","r":"120/240"},"c":25.0,"t":"Barrel (2) and Twinned Barrel: two barrels, fired one at a time or both as one attack that raises the damage die one step. Steady: as a Bonus Action if you have not moved, add your Proficiency Bonus to your next attack roll this turn and ignore long range Disadvantage, but your Speed is halved until the end of the turn. Blaring: heard 100 ft away, Disadvantage on Stealth to Hide until your next turn. Ammo: Bullet."}};
